-- Hosbah queries.

-- name: ListBucketsOfApp :many
-- Team scope: an app's buckets, by name.
SELECT * FROM app_buckets WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') ORDER BY bucket, id;

-- name: BucketOfApp :one
-- Team scope: one bucket of an app, by id or by bucket name.
SELECT * FROM app_buckets
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') AND (id = sqlc.arg('ref')::text OR bucket = sqlc.arg('ref')::text)
ORDER BY (id = sqlc.arg('ref')::text) DESC LIMIT 1;

-- name: BucketOnService :one
-- Team scope: is that bucket name taken on the service (by any app of the team)?
SELECT * FROM app_buckets WHERE service_id = sqlc.arg('service_id') AND team_id = sqlc.arg('team_id') AND bucket = sqlc.arg('bucket');

-- name: CountBucketsOfService :one
SELECT count(*) FROM app_buckets WHERE service_id = sqlc.arg('service_id') AND team_id = sqlc.arg('team_id');

-- name: InsertAppBucket :one
INSERT INTO app_buckets (id, team_id, app_id, service_id, bucket, access_key, secret_sealed, env_prefix, status)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('service_id'), sqlc.arg('bucket'), sqlc.arg('access_key'),
    sqlc.arg('secret_sealed'), sqlc.arg('env_prefix'), 'creating')
RETURNING *;

-- name: SetAppBucketStatus :execrows
-- Team scope, or the background worker (system + team). from guards the transition.
UPDATE app_buckets SET status = sqlc.arg('status'), error = sqlc.narg('error'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND status = sqlc.arg('from')::text;

-- name: DeleteAppBucketInTeam :execrows
DELETE FROM app_buckets WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: TeamBuckets :many
-- Team scope: every bucket of the team's apps with its app and MinIO service, for the team Storage page.
SELECT b.id, b.bucket, b.env_prefix, b.status, b.error, b.created_at, b.service_id, s.name AS service_name,
       a.id AS app_id, a.name AS app_name
FROM app_buckets b JOIN apps a ON a.id = b.app_id JOIN data_services s ON s.id = b.service_id
WHERE b.team_id = sqlc.arg('team_id')
ORDER BY s.name, b.bucket;
